namespace jxx::awt { MediaTracker::MediaTracker(const ::jxx::Ptr<Component>& c):Super(),component_(c){} void MediaTracker::addImage(const ::jxx::Ptr<Image>& i,::jxx::lang::jint id){if(i)entries_.push_back({i,id});} void MediaTracker::addImage(const ::jxx::Ptr<Image>& i,::jxx::lang::jint id,::jxx::lang::jint,::jxx::lang::jint){addImage(i,id);} void MediaTracker::removeImage(const ::jxx::Ptr<Image>& i){entries_.erase(std::remove_if(entries_.begin(),entries_.end(),[&](const Entry&e){return e.image==i;}),entries_.end());} void MediaTracker::removeImage(const ::jxx::Ptr<Image>& i,::jxx::lang::jint id){entries_.erase(std::remove_if(entries_.begin(),entries_.end(),[&](const Entry&e){return e.image==i&&e.id==id;}),entries_.end());} ::jxx::lang::jbool MediaTracker::checkAll(::jxx::lang::jbool)const{return true;} ::jxx::lang::jbool MediaTracker::checkID(::jxx::lang::jint,::jxx::lang::jbool)const{return true;} ::jxx::lang::jint MediaTracker::statusAll(::jxx::lang::jbool)const{return COMPLETE;} ::jxx::lang::jint MediaTracker::statusID(::jxx::lang::jint,::jxx::lang::jbool)const{return COMPLETE;} ::jxx::lang::jbool MediaTracker::isErrorAny()const{return false;} ::jxx::lang::jbool MediaTracker::isErrorID(::jxx::lang::jint)const{return false;} void MediaTracker::writeObject(const ::jxx::Ptr<::jxx::io::ObjectOutputStream>&){} void MediaTracker::readObject(const ::jxx::Ptr<::jxx::io::ObjectInputStream>&){entries_.clear();} void MediaTracker::readObjectNoData(){entries_.clear();} }
